    public function __construct($db,$actor,$entity=null){global $conf;$this->db=$db;$this->actor=$actor;$this->entity=$entity===null?(int)$conf->entity:(int)$entity;$this->tasks=new InternalTaskService($db,$actor,$this->entity);$this->auth=$this->tasks->authorization();$this->policy=new InternalTaskBoardPolicy($db,$this->auth->actorId(),$this->entity);if(!InternalTaskBoardPolicy::enabled()||!$this->auth->canOpenBoard())throw new InternalTaskAccessException('Boards access denied.');}
