    public function board($id,$role='viewer',$lock=false,$includeDeleted=false){$r=$this->rows('SELECT *, (SELECT image_hash FROM '.$this->table('board_background').' bg WHERE bg.entity='.$this->table('board').'.entity AND bg.fk_board='.$this->table('board').'.rowid) background_image FROM '.$this->table('board').' WHERE entity='.$this->entity.' AND rowid='.(int)$id.' AND '.($includeDeleted?'1=1':InternalTaskBoardLifecycle::visibleSql($this->table('board').'.entity',$this->table('board').'.rowid')).($lock?' FOR UPDATE':''));if(!$r)throw new InternalTaskAccessException('Board access denied.');$b=$r[0];$context=(new InternalTaskWorkspaceService($this->db,$this->actor,$this->entity))->boardProject($id);$b['workspace_project']=$context;$b['completed']=(new InternalTaskCompletionService($this->db,$this->actor,$this->entity))->state($id);$b['role']=$this->auth->isAdministrator()?'manager':$this->policy->role($id,$includeDeleted);if(!$b['role']||($role==='manager'&&$b['role']!=='manager')||($role==='editor'&&!in_array($b['role'],['manager','editor'],true)))throw new InternalTaskAccessException('Board access denied.');$b['can_edit']=$this->auth->isAdministrator()||$this->auth->hasRight('task_update_own')||$this->auth->hasRight('task_manage_team');$b['can_create_card']=$b['can_edit']&&($this->auth->isAdministrator()||($this->auth->hasRight('task_manage_team')&&$this->auth->hasTeamGrant($b['fk_usergroup']))||$this->auth->canCreateOwnTask($b['fk_usergroup']));if($context&&InternalTaskProjectTaskService::enabled())$b['can_create_card']=$b['can_create_card']&&(new InternalTaskProjectTaskService($this->db,$this->actor,$this->entity))->canCreate($context['rowid']);if(SupplierWorkspaceService::enabled()){
        $supplier=new SupplierWorkspaceService($this->db,$this->actor,$this->entity);
        $b['supplier_context']=$supplier->context((int)$id);
