    public function people($staffOnly=false){if(!$this->auth->isInternalActive())throw new InternalTaskAccessException('Access denied.');return $this->rows('SELECT rowid,login,firstname,lastname FROM '.MAIN_DB_PREFIX.'user WHERE entity='.$this->entity." AND statut=1 AND COALESCE(fk_soc,0)=0".($staffOnly?" AND employee=1":"")." ORDER BY firstname,login");}
    public function gallery($archive=false,$genericOnly=false){$where=$this->auth->isAdministrator()?'1=1':'EXISTS (SELECT 1 FROM '.$this->table('board_member').' m WHERE m.entity=b.entity AND m.fk_board=b.rowid AND m.fk_user='.$this->auth->actorId().')';$where.=($genericOnly&&InternalTaskWorkspaceService::enabled())?' AND NOT EXISTS (SELECT 1 FROM '.MAIN_DB_PREFIX.'cpo_project_board ws_gp WHERE ws_gp.entity=b.entity AND ws_gp.fk_board=b.rowid)':'';if($genericOnly&&SupplierWorkspaceService::enabled())$where.=' AND NOT '.(new SupplierWorkspaceService($this->db,$this->actor,$this->entity))->mappingSql('b.entity','b.rowid');$boards=$this->rows('SELECT b.*,(SELECT image_hash FROM '.$this->table('board_background').' bg WHERE bg.entity=b.entity AND bg.fk_board=b.rowid) background_image,COALESCE(p.starred,0) starred,p.last_opened FROM '.$this->table('board').' b LEFT JOIN '.$this->table('board_pref').' p ON p.entity=b.entity AND p.fk_board=b.rowid AND p.fk_user='.$this->auth->actorId().' WHERE b.entity='.$this->entity.' AND b.archived='.(int)$archive.' AND '.$where.' AND '.InternalTaskBoardLifecycle::visibleSql('b.entity','b.rowid').' ORDER BY starred DESC,last_opened DESC,b.rowid DESC');foreach($boards as $key=>&$b){try{$b['workspace_project']=(new InternalTaskWorkspaceService($this->db,$this->actor,$this->entity))->boardProject($b['rowid']);}catch(InternalTaskAccessException $e){unset($boards[$key]);continue;}$b['role']=$this->auth->isAdministrator()?'manager':$this->policy->role($b['rowid']);$b['completed']=(new InternalTaskCompletionService($this->db,$this->actor,$this->entity))->state($b['rowid']);}$boards=array_values($boards);return ['boards'=>$boards,'can_create'=>$this->auth->isAdministrator(),'teams'=>$this->auth->isAdministrator()?$this->teams():[],'people'=>$this->auth->isAdministrator()?$this->people($genericOnly):[]];}
    private function cards($board,$archived){$rows=$this->rows('SELECT c.*,t.title,t.ref,t.status,t.priority,t.version task_version,t.date_archived,t.date_deadline,t.fk_user_assign FROM '.$this->table('board_card').' c INNER JOIN '.$this->table('task').' t ON t.entity=c.entity AND t.rowid=c.fk_task WHERE c.entity='.$this->entity.' AND c.fk_board='.(int)$board.' AND '.($archived?'(c.archived=1 OR t.date_archived IS NOT NULL)':'c.archived=0 AND t.date_archived IS NULL')." AND t.status<>'deleted' ORDER BY c.position,c.rowid");$contextService=null;if(!empty($GLOBALS['conf']->global->CPO_SHIPMENT_CARDS_ENABLED)){require_once __DIR__.'/InternalTaskContextService.class.php';$contextService=new InternalTaskContextService($this->db,$this->actor,$this->entity);}$tasks=[];foreach($rows as &$r){$task=$this->tasks->requireReadableTask($r['fk_task']);$tasks[]=$task;$r['erp']=[];if($contextService){$context=$contextService->getReferences($r['fk_task'])['context'];foreach(['customer','shipment','project'] as $type)if(!empty($context[$type]))$r['erp'][$type]=$context[$type]['label'];}$r['editable']=$this->auth->canEditTask($task);$r['can_complete']=InternalTaskCompletionService::enabled()&&$this->auth->canManageTask($task);$r['assignee']=$task['assignee_name']??($task['assignee_login']??'');$r['asset_count']=$this->auth->canUseTaskFiles($task,false,false)?(int)($task['asset_count']??0):0;$r['cover_asset_id']=$this->auth->canUseTaskFiles($task,false,false)?(int)($task['cover_asset_id']??0):0;}unset($r);$details=(new InternalTaskDetailsService($this->db,$this->actor,$this->entity))->forBoard($tasks);$counters=(new InternalTaskCollaborationService($this->db,$this->actor,$this->entity))->counters(array_column($tasks,'rowid'));foreach($rows as &$r){$r['details']=$details[$r['fk_task']]??[];$r['counters']=$counters[$r['fk_task']]??[];}return $rows;}
    public function workspace($id,$archive=false){$b=$this->board($id);$lists=$this->rows('SELECT * FROM '.$this->table('board_list').' WHERE entity='.$this->entity.' AND fk_board='.(int)$id.' ORDER BY position,rowid');$members=$this->rows('SELECT m.fk_user,m.role,u.login,u.firstname,u.lastname FROM '.$this->table('board_member').' m INNER JOIN '.MAIN_DB_PREFIX.'user u ON u.rowid=m.fk_user AND u.entity=m.entity WHERE m.entity='.$this->entity.' AND m.fk_board='.(int)$id.' ORDER BY m.rowid');$result=['completion_enabled'=>InternalTaskCompletionService::enabled(),'board'=>$b,'lists'=>$lists,'cards'=>$this->cards($id,false),'archived_cards'=>$this->cards($id,true),'members'=>$members,'people'=>$b['role']==='manager'?$this->people($b['staff_only_members']):[]];$r=$this->rows('SELECT '.InternalTaskBoardCounts::expression($this->entity,(int)$id,false).' open_tasks,'.InternalTaskBoardCounts::expression($this->entity,(int)$id,true).' done_tasks');$result['counts']=array_map('intval',$r[0]);if($b['role']==='manager')$result['grants']=$this->rows('SELECT g.fk_task,g.fk_user,g.role FROM '.$this->table('card_grant').' g INNER JOIN '.$this->table('board_card').' c ON c.entity=g.entity AND c.fk_task=g.fk_task WHERE c.entity='.$this->entity.' AND c.fk_board='.(int)$id);return $result;}
