        require_once __DIR__.'/InternalTaskBoardPresentation.class.php';
        $p=(new InternalTaskBoardPresentation($this->db,$this->actor,$this->entity))->load(['view'=>'my']);$tasks=$p['tasks'];$details=(new InternalTaskDetailsService($this->db,$this->actor,$this->entity))->forBoard($tasks);$counters=(new InternalTaskCollaborationService($this->db,$this->actor,$this->entity))->counters(array_column($tasks,'rowid'));global $langs;$lang=strpos($langs->defaultlang,'ar')===0?'label_ar':'label_en';$lists=[];foreach($p['columns'] as $c)$lists[]=array_merge($c,['title'=>$c[$lang],'archived'=>0]);$cards=[];foreach($tasks as $t)$cards[]=array_merge($t,['fk_task'=>$t['rowid'],'fk_list'=>$t['personal_column'],'task_version'=>$t['version'],'editable'=>$this->auth->canEditTask($t),'details'=>$details[$t['rowid']]??[],'counters'=>$counters[$t['rowid']]??[],'asset_count'=>$this->auth->canUseTaskFiles($t,false,false)?(int)$t['asset_count']:0,'cover_asset_id'=>$this->auth->canUseTaskFiles($t,false,false)?(int)$t['cover_asset_id']:0]);return ['personal'=>true,'personal_state'=>$p['state'],'board'=>['title'=>'My Work','role'=>'editor','background'=>'#172b4d','version'=>$p['state']['version'],'archived'=>0,'can_edit'=>true],'lists'=>$lists,'cards'=>$cards,'archived_cards'=>[],'members'=>[],'people'=>[]];
