    private function assignedSummary($archived=false){
        // Keep the saved personal arrangement dormant. Summary reads only canonical tasks/placements.
        $p=MAIN_DB_PREFIX;$uid=$this->auth->actorId();
        $isArchived="(t.date_archived IS NOT NULL OR t.status='cancelled' OR COALESCE(bc.archived,0)=1 OR COALESCE(b.archived,0)=1 OR COALESCE(bl.archived,0)=1)";
