        require_once __DIR__.'/InternalTaskContextService.class.php';$context=new InternalTaskContextService($this->db,$this->actor,$this->entity);$tasks=[];
        foreach($this->rows($sql) as $r){$id=(int)$r['rowid'];$linked=$context->getReferences($id);$tasks[$id]=['id'=>$id,'title'=>$r['title'],'ref'=>$r['ref'],'status'=>$r['status'],'priority'=>$r['priority'],'date_deadline'=>$r['date_deadline'],'archived'=>(bool)$r['archived'],'board'=>$r['board_id']?['id'=>(int)$r['board_id'],'title'=>$r['board_title']]:null,'list'=>$r['list_id']?['id'=>(int)$r['list_id'],'title'=>$r['list_title']]:null,'location'=>!$r['placement_id']?'unplaced':(!$r['board_id']?'restricted':($r['archived']?'archived':'available')),'shipment'=>$linked['context']['shipment']??null];}
