    public function search($term){$term=$this->text($term,200);if(mb_strlen($term)<2)return [];$like=$this->q('%'.$term.'%');return $this->rows('SELECT t.rowid,t.title,t.ref,t.status FROM '.$this->table('task').' t WHERE t.entity='.$this->entity." AND t.status<>'deleted' AND ".$this->auth->readableSql('t').' AND (t.title LIKE '.$like.' OR t.ref LIKE '.$like.') ORDER BY t.rowid DESC LIMIT 100');}
