            require_once __DIR__.'/InternalTaskContextService.class.php';
            (new InternalTaskContextService($this->db,$this->actor,$this->entity))->inheritBoardContext($id,$b['workspace_project']);
            $bridge->createForCard($id,$b['rowid'],$b['workspace_project']['rowid']);
            $this->query('RELEASE SAVEPOINT cpo_native_project_card');return $id;
        }catch(Throwable $e){$this->query('ROLLBACK TO SAVEPOINT cpo_native_project_card');$this->query('RELEASE SAVEPOINT cpo_native_project_card');throw $e;}
    }
    private function addCardContents($b,$list,$title,$request,$copy=null,$copyComments=false){$this->listRow($list,$b['rowid']);$uid=$this->auth->actorId();$id=$this->tasks->createTask(['title'=>$title,'description'=>$copy['description']??$title,'fk_usergroup'=>$b['fk_usergroup'],'fk_user_assign'=>$this->auth->isActiveTeamMember($uid,$b['fk_usergroup'])?$uid:0,'priority'=>$copy['priority']??'normal','date_deadline'=>$copy['date_deadline']??'','request_hash'=>hash('sha256',$this->entity.':'.$uid.':'.$request)],false,false);$r=$this->rows('SELECT * FROM '.$this->table('board_card').' WHERE entity='.$this->entity.' AND fk_task='.$id);if($r){if((int)$r[0]['fk_board']!==(int)$b['rowid']||(int)$r[0]['fk_list']!==(int)$list)throw new InternalTaskConflictException('Card request changed.');return $id;}$this->query('INSERT INTO '.$this->table('board_card').'(entity,fk_board,fk_list,fk_task,position) SELECT '.$this->entity.','.(int)$b['rowid'].','.(int)$list.','.$id.',COALESCE(MAX(position),0)+1024 FROM '.$this->table('board_card').' WHERE entity='.$this->entity.' AND fk_list='.(int)$list);if($copy){$details=(new InternalTaskDetailsService($this->db,$this->actor,$this->entity))->get($copy['rowid']);(new InternalTaskDetailsService($this->db,$this->actor,$this->entity))->save($id,0,$details['data']);$collab=new InternalTaskCollaborationService($this->db,$this->actor,$this->entity);foreach($collab->listChecklists($copy['rowid']) as $cl){$new=$collab->createChecklist($id,$cl['title']);foreach($cl['items'] as $item){$newItem=$collab->createItem($id,$new,$item['label']);if($item['completed'])$collab->mutateItem($id,$newItem,1,'toggle');}}$labels=array_filter($collab->taskLabels($copy['rowid']),function($l){return !empty($l['active']);});if($labels)$collab->setTaskLabels($id,array_column($labels,'rowid'),$collab->labelFingerprint($id));if($copyComments){$cursorDate='';$cursorId=0;do{$comments=$collab->listComments($copy['rowid'],$cursorDate,$cursorId);foreach($comments as $comment){if($comment['visibility']!=='redacted'){$uuid=bin2hex(random_bytes(16));$key=substr($uuid,0,8).'-'.substr($uuid,8,4).'-4'.substr($uuid,13,3).'-8'.substr($uuid,17,3).'-'.substr($uuid,20,12);$collab->createComment($id,$comment['body'],[],$key);}}if($comments){$cursorDate=$comments[0]['date_creation'];$cursorId=$comments[0]['rowid'];}}while(count($comments)===50);}}return $id;}
